import fs from 'node:fs';
import { pathToFileURL } from 'node:url';

// Rebuilds CHANGELOG.md / CHANGELOG_EN.md from release-notes/<tag>.<lang>.md.
// Only published stable releases are listed, so a version burned by a failed
// build or a pre-release never shows up. Regenerated in full each run, so a
// missed run heals itself on the next release.

const REPO_URL = 'https://github.com/Kyosee/VeneraX';

export const LANGS = {
  'zh-CN': {
    file: 'CHANGELOG.md',
    title: '# 更新日志',
    switcher: '中文 | [English](CHANGELOG_EN.md)',
    older: `更早的版本见 [GitHub Releases](${REPO_URL}/releases)。`,
  },
  en: {
    file: 'CHANGELOG_EN.md',
    title: '# Changelog',
    switcher: '[中文](CHANGELOG.md) | English',
    older: `Older versions are listed on [GitHub Releases](${REPO_URL}/releases).`,
  },
};

const STABLE_TAG = /^v(\d+)\.(\d+)\.(\d+)$/;

function compareTags(a, b) {
  const pa = a.match(STABLE_TAG).slice(1).map(Number);
  const pb = b.match(STABLE_TAG).slice(1).map(Number);
  for (let i = 0; i < 3; i++) {
    if (pa[i] !== pb[i]) return pb[i] - pa[i];
  }
  return 0;
}

// Input lines are `<tag>\t<published_at>`; returns newest first.
export function parseReleases(text) {
  const releases = [];
  for (const line of text.split(/\r?\n/)) {
    const [tag, publishedAt] = line.trim().split('\t');
    if (!tag || !STABLE_TAG.test(tag) || !publishedAt) continue;
    releases.push({ tag, date: publishedAt.slice(0, 10) });
  }
  return releases.sort((a, b) => compareTags(a.tag, b.tag));
}

// Drops the per-file `## What's Changed` title; the version heading replaces it.
export function notesBody(markdown) {
  return markdown
    .replace(/\r\n/g, '\n')
    .split('\n')
    .filter((line) => !/^#{1,2} /.test(line))
    .join('\n')
    .trim();
}

export function buildChangelog(lang, entries) {
  const l = LANGS[lang];
  const parts = [
    '<!-- Generated by .github/scripts/gen-changelog.mjs after each stable release. Edit release-notes/ instead. -->',
    l.title,
    l.switcher,
  ];
  for (const { tag, date, body } of entries) {
    parts.push(`## [${tag}](${REPO_URL}/releases/tag/${tag}) - ${date}`, body);
  }
  parts.push(l.older);
  return parts.join('\n\n') + '\n';
}

function main() {
  const releases = parseReleases(fs.readFileSync(process.env.RELEASES_FILE, 'utf8'));
  if (releases.length === 0) throw new Error('No stable releases found');
  const notesDir = process.env.NOTES_DIR || 'release-notes';

  for (const [lang, l] of Object.entries(LANGS)) {
    const entries = [];
    for (const { tag, date } of releases) {
      const path = `${notesDir}/${tag}.${lang}.md`;
      if (!fs.existsSync(path)) continue;
      entries.push({ tag, date, body: notesBody(fs.readFileSync(path, 'utf8')) });
    }
    // Refuse to replace the history with an empty file.
    if (entries.length === 0) throw new Error(`No ${lang} release notes found`);

    const out = buildChangelog(lang, entries);
    const before = fs.existsSync(l.file) ? fs.readFileSync(l.file, 'utf8') : '';
    fs.writeFileSync(l.file, out);
    console.log(`${l.file}: ${before === out ? 'unchanged' : 'updated'} (${entries.length} versions)`);
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
